// Pathophysiology Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test
// plan, slightly harder than the sample items: they ask for the mechanism behind a disease,
// not just its name.
import {q, mix} from './q.js';
const FRA='Frazier, Essentials of Human Diseases and Conditions', ZEL='Zelman et al., Human Diseases: A Systemic Approach', ICEV='iCEV Pathophysiology course';
const DP='Disease Process & Terminology', INTEG='Integumentary', MSK='Musculoskeletal', CIRC='Circulatory & Lymphatic', RESP='Respiratory', DIG='Digestive', ENDO='Endocrine', NERV='Nervous & Senses', REPRO='Reproductive', URIN='Urinary', MENT='Mental Disorders';

export default {
 id:'pathophysiology-1',
 event:'Pathophysiology',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Frazier’s Essentials of Human Diseases and Conditions, Zelman’s Human Diseases, and the iCEV Pathophysiology course',
 plan:[{area:DP,weight:12},{area:INTEG,weight:8},{area:MSK,weight:10},{area:CIRC,weight:12},{area:RESP,weight:8},{area:DIG,weight:12},{area:ENDO,weight:8},{area:NERV,weight:10},{area:REPRO,weight:6},{area:URIN,weight:6},{area:MENT,weight:8}],
 questions:mix([
  q(DP,'Which statement correctly describes apoptosis?','Programmed cell death that does not trigger inflammation',['Cell death from injury that releases contents and causes inflammation','An increase in the size of individual cells','The change of one mature cell type into another'],'B','Apoptosis is orderly, genetically programmed cell death; the cell shrinks and is removed without inflammation. Necrosis is uncontrolled death from injury, hypertrophy is an increase in cell size, and metaplasia is a change in cell type.',ZEL),
  q(DP,'In a long-term smoker, ciliated columnar cells lining the bronchi are replaced by tougher stratified squamous cells. What is this adaptation called?','Metaplasia',['Hyperplasia','Dysplasia','Anaplasia'],'A','Metaplasia is the reversible replacement of one mature cell type with another better able to withstand stress. Hyperplasia is an increase in cell number, dysplasia is disordered growth, and anaplasia is loss of differentiation seen in cancer.',ZEL),
  q(DP,'Which feature best distinguishes a malignant tumor from a benign one?','It invades nearby tissue and can metastasize',['It is surrounded by a fibrous capsule','Its cells closely resemble normal cells','It grows slowly and pushes tissue aside'],'D','Malignant tumors invade surrounding tissue and spread through blood or lymph. Benign tumors are usually encapsulated, well differentiated and slow growing, and they do not metastasize.',FRA),
  q(DP,'In the TNM cancer staging system, what does the N describe?','Spread to regional lymph nodes',['Number of tumors present','Necrosis within the tumor','Grade of nuclear abnormality'],'C','T describes the size and extent of the primary tumor, N describes regional lymph node involvement, and M describes distant metastasis.',FRA),
  q(DP,'A disease whose cause cannot be identified is described as:','Idiopathic',['Iatrogenic','Nosocomial','Congenital'],'B','Idiopathic means of unknown cause. Iatrogenic conditions are caused by medical treatment, nosocomial infections are acquired in a healthcare facility, and congenital conditions are present at birth.',FRA),
  q(DP,'During acute inflammation, local vasodilation directly produces which two cardinal signs?','Redness and heat',['Swelling and pain','Pain and loss of function','Heat and loss of function'],'A','Vasodilation brings more warm blood to the area, causing redness (rubor) and heat (calor). Increased capillary permeability causes swelling, and chemical mediators and pressure on nerves cause pain.',ZEL),
  q(INTEG,'A patient has well-defined red plaques with silvery scales on the elbows and knees, caused by skin cells turning over much faster than normal. Which condition is this?','Psoriasis',['Atopic dermatitis','Seborrheic keratosis','Tinea corporis'],'C','Psoriasis is a chronic, immune-mediated disease in which keratinocytes mature in days instead of weeks, producing thick plaques with silvery scale on extensor surfaces. It is not contagious.',FRA),
  q(INTEG,'In the ABCDE rule for evaluating moles for melanoma, what does E stand for?','Evolving over time',['Elevation above the skin surface','Erythema around the border','Exposure to ultraviolet light over time'],'D','ABCDE stands for Asymmetry, Border irregularity, Color variation, Diameter larger than about 6 mm, and Evolving. A mole that changes over time is the most concerning sign.',FRA),
  q(INTEG,'Herpes zoster (shingles) results from reactivation of which virus?','Varicella-zoster virus',['Herpes simplex virus type 1','Human papillomavirus','Epstein-Barr virus'],'A','After chickenpox, varicella-zoster virus stays dormant in sensory nerve ganglia. When reactivated, it causes a painful, blistering rash along one dermatome, usually on one side of the body.',FRA),
  q(INTEG,'A child has red sores around the nose and mouth that rupture and form honey-colored crusts. Which infection is most likely?','Impetigo',['Cellulitis','Herpes simplex','Contact dermatitis'],'B','Impetigo is a highly contagious superficial skin infection caused by Staphylococcus aureus or Streptococcus pyogenes, recognized by honey-colored crusts. Cellulitis is a deeper infection with spreading redness and warmth.',FRA),
  q(MSK,'A man wakes with a hot, red, extremely painful big toe after a night of heavy drinking. What is the underlying cause of this condition?','Deposits of uric acid crystals in the joint',['Autoimmune attack on the joint lining','Wearing away of joint cartilage','Bacterial infection of the joint'],'D','This is gout. High blood uric acid forms monosodium urate crystals in the joint, often the first joint of the big toe. Alcohol and purine-rich foods can trigger attacks.',FRA),
  q(MSK,'Which finding suggests rheumatoid arthritis rather than osteoarthritis?','Symmetric joint swelling with morning stiffness lasting over an hour',['Bony enlargements at the finger joints closest to the nails','Joint pain that worsens with use and improves with rest','Stiffness affecting only one weight-bearing joint'],'A','Rheumatoid arthritis is a systemic autoimmune disease causing symmetric inflammation and prolonged morning stiffness. Osteoarthritis is wear-and-tear degeneration, with Heberden’s nodes and pain that worsens with use.',ZEL),
  q(MSK,'Why are postmenopausal women at increased risk for osteoporosis?','Lower estrogen lets bone loss outpace bone formation',['Menopause blocks absorption of vitamin D','Calcium is lost through increased urination','Menopause increases parathyroid hormone production'],'C','Estrogen helps restrain osteoclast activity. When estrogen falls after menopause, bone is broken down faster than it is rebuilt, lowering bone density and raising fracture risk.',ZEL),
  q(MSK,'A 5-year-old boy uses his hands to “walk” up his legs to stand from the floor (Gowers’ sign). Which disorder is most likely, and how is it inherited?','Duchenne muscular dystrophy, X-linked recessive',['Spinal muscular atrophy, autosomal dominant','Myasthenia gravis, X-linked dominant','Cerebral palsy, autosomal recessive'],'B','Duchenne muscular dystrophy is caused by a mutation in the dystrophin gene on the X chromosome, so it mostly affects boys. Weak hip and thigh muscles produce Gowers’ sign.',FRA),
  q(MSK,'Carpal tunnel syndrome causes numbness of the thumb, index and middle fingers because of compression of which nerve?','Median nerve',['Ulnar nerve','Radial nerve','Musculocutaneous nerve'],'A','The median nerve passes through the carpal tunnel with the flexor tendons. Swelling in the tunnel compresses it, affecting sensation in the thumb, index finger, middle finger and part of the ring finger.',FRA),
  q(CIRC,'A patient with left-sided heart failure is most likely to have which finding?','Dyspnea and crackles from fluid in the lungs',['Pitting swelling of both ankles and legs','Distended neck veins and an enlarged liver','Ascites from congestion of the abdominal veins'],'C','When the left ventricle fails, blood backs up into the pulmonary circulation, causing pulmonary congestion, dyspnea and crackles. Right-sided failure backs blood up into the body, causing peripheral edema, neck vein distension and liver enlargement.',ZEL),
  q(CIRC,'Which blood test is the most specific marker of injury to heart muscle?','Cardiac troponin',['Total creatine kinase','Lactate dehydrogenase','Brain natriuretic peptide'],'D','Troponin is a protein released when cardiac muscle cells are damaged and is the preferred test for diagnosing myocardial infarction. Total CK and LDH also rise with skeletal muscle injury, and BNP reflects heart failure.',FRA),
  q(CIRC,'Pernicious anemia develops because the body lacks:','Intrinsic factor, which is needed to absorb vitamin B12',['Iron, which is needed to make hemoglobin','Folic acid, which is needed to make platelets','Erythropoietin, which signals the marrow to make cells'],'A','In pernicious anemia, autoimmune damage to the stomach lining stops production of intrinsic factor, so vitamin B12 cannot be absorbed. The result is large, immature red cells (megaloblastic anemia). Erythropoietin is made by the kidneys.',FRA),
  q(CIRC,'Which statement describes primary (essential) hypertension?','High blood pressure with no single identifiable cause',['High blood pressure caused by kidney disease','High blood pressure that occurs only during pregnancy','A sudden, severe rise in blood pressure with organ damage'],'B','About 90% of adults with hypertension have primary hypertension, linked to genetics, age, diet and lifestyle. Secondary hypertension has a specific cause, such as kidney or adrenal disease.',ZEL),
  q(CIRC,'Which three factors make up Virchow’s triad for venous thrombosis?','Blood stasis, vessel wall injury and hypercoagulability',['High blood pressure, high cholesterol and smoking','Anemia, infection and dehydration','Vasodilation, low platelets and inflammation'],'C','Slow blood flow (as in immobility), damage to the vessel lining, and blood that clots too easily together promote deep vein thrombosis. A DVT can break loose and cause a pulmonary embolism.',ZEL),
  q(CIRC,'The presence of Reed-Sternberg cells in a lymph node biopsy indicates which cancer?','Hodgkin lymphoma',['Non-Hodgkin lymphoma','Acute lymphocytic leukemia','Multiple myeloma'],'D','Reed-Sternberg cells, large abnormal B cells with two nuclei, are the hallmark of Hodgkin lymphoma. They are absent in non-Hodgkin lymphoma.',FRA),
  q(RESP,'In emphysema, which change causes air to become trapped in the lungs?','Destroyed alveolar walls and lost elastic recoil',['Thick mucus plugs blocking the small bronchi','Fluid filling the alveoli','Fibrous scarring that stiffens the lung tissue'],'A','Emphysema destroys alveolar walls and the elastic fibers that help the lungs recoil. Air enters easily but cannot be pushed out, causing hyperinflation and a barrel chest. Thick mucus is typical of chronic bronchitis.',ZEL),
  q(RESP,'Which feature best distinguishes asthma from chronic obstructive pulmonary disease (COPD)?','Its obstruction is largely reversible',['It always begins after age 40','It involves no airway inflammation','It is caused mainly by cigarette smoking'],'B','Asthma involves airway inflammation, bronchospasm and mucus that improve with bronchodilators or between attacks. COPD obstruction is progressive and largely irreversible.',FRA),
  q(RESP,'A person with latent tuberculosis infection has a positive TB skin test but a normal chest X-ray and no symptoms. Which statement is true?','They are not contagious but may develop active TB later',['The person is contagious and must be isolated','The person has been cured and needs no follow-up','The person has active TB that is not yet visible'],'D','In latent TB, the immune system walls off Mycobacterium tuberculosis. The person is not infectious, but the bacteria can reactivate, so preventive treatment is often recommended.',FRA),
  q(RESP,'Cystic fibrosis is diagnosed with a sweat chloride test because the disease affects:','A channel that moves chloride across cell membranes',['The production of surfactant by alveolar cells','The number of sweat glands in the skin','The kidneys’ ability to excrete excess salt'],'C','Mutations in the CFTR gene disrupt a chloride channel. Secretions become thick and sticky in the lungs and pancreas, and sweat contains abnormally high levels of chloride. It is inherited in an autosomal recessive pattern.',ZEL),
  q(DIG,'Gastroesophageal reflux disease (GERD) is caused mainly by:','A lower esophageal sphincter that does not close properly',['Too little acid produced by the stomach','A blockage at the pyloric sphincter','Infection of the esophagus by Helicobacter pylori'],'B','When the lower esophageal sphincter relaxes inappropriately, stomach acid flows back into the esophagus. Long-term reflux can cause Barrett’s esophagus, a precancerous change.',FRA),
  q(DIG,'What are the two most common causes of peptic ulcers?','Helicobacter pylori infection and NSAID use',['Spicy foods and prolonged emotional stress','Alcohol use and high-fat diets','Gallstones and chronic pancreatitis'],'A','H. pylori damages the protective mucus layer, and NSAIDs reduce the prostaglandins that protect the stomach lining. Stress and spicy foods may worsen symptoms but do not cause ulcers.',FRA),
  q(DIG,'Which description fits Crohn’s disease rather than ulcerative colitis?','Inflammation through the full bowel wall, with skip areas anywhere from mouth to anus',['Continuous inflammation of the inner lining that starts in the rectum','Inflammation limited to the colon and rectum','Bloody diarrhea is the main symptom, and fistulas are rare'],'C','Crohn’s disease is transmural, can affect any part of the GI tract and leaves healthy “skip” areas between diseased segments; fistulas are common. Ulcerative colitis affects only the mucosa of the colon and rectum in a continuous pattern.',ZEL),
  q(DIG,'A patient with cirrhosis vomits large amounts of blood. Which complication of cirrhosis explains this?','Ruptured esophageal varices from portal hypertension',['Low albumin causing fluid in the abdomen','Bile duct blockage causing severe jaundice','Buildup of ammonia affecting the brain'],'D','Scarring of the liver increases pressure in the portal vein. Blood is diverted into thin-walled veins of the esophagus (varices), which can rupture and bleed severely.',FRA),
  q(DIG,'Which two hepatitis viruses are spread mainly by the fecal-oral route?','Hepatitis A and hepatitis E',['Hepatitis B and hepatitis C','Hepatitis B and hepatitis D','Hepatitis C and hepatitis E'],'A','Hepatitis A and E spread through contaminated food and water and do not cause chronic infection. Hepatitis B, C and D spread through blood and body fluids and can become chronic.',FRA),
  q(DIG,'Pain that begins around the umbilicus and moves to McBurney’s point in the right lower quadrant suggests which condition?','Appendicitis',['Diverticulitis','Cholecystitis','Pancreatitis'],'B','Early appendicitis causes vague pain around the navel; as the inflamed appendix irritates the nearby peritoneum, pain localizes to the right lower quadrant. Diverticulitis usually causes left lower quadrant pain, and cholecystitis causes right upper quadrant pain.',FRA),
  q(ENDO,'What causes type 1 diabetes mellitus?','Autoimmune destruction of the insulin-producing beta cells',['Cells that become resistant to the effects of insulin','A shortage of glucagon from the alpha cells','A pituitary gland that makes too little hormone'],'C','In type 1 diabetes, the immune system destroys pancreatic beta cells, so the body makes little or no insulin and insulin injections are required. Insulin resistance is the main problem in type 2 diabetes.',FRA),
  q(ENDO,'A patient has weight loss, heat intolerance, a rapid heart rate and bulging eyes. Antibodies are stimulating the TSH receptor. Which disorder is this?','Graves’ disease',['Hashimoto’s thyroiditis','Cushing’s syndrome','Addison’s disease'],'D','In Graves’ disease, antibodies mimic TSH and drive the thyroid to overproduce hormone, causing hyperthyroidism and exophthalmos. Hashimoto’s thyroiditis is autoimmune hypothyroidism.',ZEL),
  q(ENDO,'Which set of findings suggests Addison’s disease (primary adrenal insufficiency)?','Darkened skin, low blood pressure and fatigue',['Moon face, a buffalo hump and purple stretch marks','Excessive thirst and very dilute urine','Weight gain, cold intolerance and dry skin'],'A','In Addison’s disease, the adrenal cortex makes too little cortisol and aldosterone, causing fatigue, hypotension and salt craving. High ACTH darkens the skin. A moon face and buffalo hump are signs of excess cortisol (Cushing’s).',FRA),
  q(ENDO,'Central diabetes insipidus causes the production of large amounts of dilute urine because of a deficiency of:','ADH',['Insulin','Aldosterone','Cortisol'],'B','ADH from the posterior pituitary tells the kidneys to reabsorb water. Without it, the kidneys cannot concentrate urine, so the person urinates large volumes and is very thirsty. Blood glucose is normal.',ZEL),
  q(NERV,'What is the underlying process in multiple sclerosis?','Autoimmune destruction of myelin in the brain and spinal cord',['Motor neurons in the brain and spinal cord degenerate','Dopamine-producing neurons in the brain are lost','Antibodies block acetylcholine at the muscle junction'],'C','MS is an autoimmune disease that attacks myelin in the central nervous system, slowing or blocking nerve signals. Motor neuron degeneration is ALS, dopamine loss is Parkinson’s disease, and acetylcholine receptor antibodies cause myasthenia gravis.',ZEL),
  q(NERV,'Which brain changes are characteristic of Alzheimer’s disease?','Beta-amyloid plaques and neurofibrillary tangles',['Small infarcts from blocked arteries','Lewy bodies in the substantia nigra','Demyelinated plaques in the white matter'],'A','Alzheimer’s disease is marked by beta-amyloid plaques between neurons and tangles of tau protein inside them, leading to neuron loss and brain atrophy. Multiple small infarcts cause vascular dementia.',FRA),
  q(NERV,'Open-angle glaucoma damages the optic nerve. Which pattern of vision loss does it usually cause first?','Gradual loss of peripheral vision',['Sudden loss of central vision','Blurred, cloudy vision with glare','Double vision when looking to the side'],'D','Increased intraocular pressure from poor drainage of aqueous humor slowly damages the optic nerve, starting with peripheral vision. Many people do not notice it until damage is advanced, so screening is important.',FRA),
  q(NERV,'Why are young children more likely than adults to develop otitis media?','Their eustachian tubes are shorter and more horizontal',['Their eardrums are thicker and much less flexible','Their ear canals produce less earwax','Their middle ears contain more fluid at birth'],'B','A short, horizontal eustachian tube drains poorly and lets bacteria from the throat reach the middle ear more easily, especially during colds.',FRA),
  q(NERV,'In myasthenia gravis, muscle weakness that worsens with activity is caused by:','Antibodies against acetylcholine receptors on muscle',['Degeneration of upper and lower motor neurons','Loss of dopamine-producing neurons','Inflammation of the peripheral nerves after infection'],'A','Autoantibodies reduce the number of working acetylcholine receptors, so repeated muscle use quickly causes weakness, often first in the eyelids and eye muscles. Motor neuron degeneration describes ALS, and post-infection nerve inflammation describes Guillain-Barré syndrome.',ZEL),
  q(REPRO,'What is endometriosis?','Endometrial tissue growing outside the uterus',['A thickened uterine lining from too much estrogen','A benign tumor of the uterine muscle','Infection of the uterus and fallopian tubes'],'C','In endometriosis, tissue like the uterine lining grows on the ovaries, tubes or pelvic lining and bleeds with each cycle, causing pain and sometimes infertility. A benign muscle tumor is a fibroid (leiomyoma).',FRA),
  q(REPRO,'Benign prostatic hyperplasia causes urinary hesitancy and a weak stream mainly because:','The enlarged prostate compresses the urethra',['Cancer cells block the bladder neck','The bladder muscle loses its nerve supply','Infection narrows the ureters'],'D','The prostate surrounds the urethra just below the bladder. As it enlarges with age, it squeezes the urethra, making urination difficult and leaving urine in the bladder.',FRA),
  q(REPRO,'Where does an ectopic pregnancy most often implant?','In a fallopian tube',['On the ovary','In the abdominal cavity','In the cervix'],'B','About 95% of ectopic pregnancies implant in a fallopian tube. As the embryo grows, the tube can rupture and cause life-threatening internal bleeding.',ZEL),
  q(URIN,'Two weeks after strep throat, a child has cola-colored urine, puffy eyes and high blood pressure. Which condition is most likely?','Acute glomerulonephritis',['Pyelonephritis','Nephrolithiasis','Polycystic kidney disease'],'A','Post-streptococcal glomerulonephritis occurs when immune complexes damage the glomeruli, letting blood and protein into the urine and causing fluid retention and hypertension. Pyelonephritis is a bacterial infection with fever and flank pain.',FRA),
  q(URIN,'Why are urinary tract infections more common in women than in men?','Women have a shorter urethra closer to the anus',['Women produce more acidic, irritating urine','Women have smaller kidneys and ureters','Women’s bladders empty more slowly'],'C','A short urethra located near the anus makes it easier for intestinal bacteria such as E. coli to reach the bladder.',FRA),
  q(URIN,'What is the most common type of kidney stone?','Calcium oxalate',['Uric acid','Magnesium struvite','Cystine'],'D','About 80% of kidney stones contain calcium, most often calcium oxalate. Uric acid stones are linked to gout, struvite stones to urinary infections, and cystine stones to a rare inherited disorder.',FRA),
  q(MENT,'Which is a positive symptom of schizophrenia?','Hallucinations',['Flat affect','Withdrawal','Lack of motivation'],'B','Positive symptoms are additions to normal experience, such as hallucinations, delusions and disorganized speech. Negative symptoms are losses, such as flat affect, withdrawal and lack of motivation.',FRA),
  q(MENT,'What is required for a diagnosis of bipolar I disorder?','At least one manic episode',['At least one major depressive episode','Alternating moods within a single day','Mood swings lasting at least two years'],'A','Bipolar I requires at least one full manic episode lasting a week or more (or requiring hospitalization). Depressive episodes are common but not required. Bipolar II involves hypomania and major depression.',FRA),
  q(MENT,'Which description best fits generalized anxiety disorder?','Hard-to-control worry about many things, most days, for 6+ months',['Sudden, repeated attacks of intense fear with a pounding heart','Intense fear of a specific object or situation','Anxiety that follows a traumatic event, with flashbacks'],'D','Generalized anxiety disorder is persistent worry about everyday matters. Sudden attacks describe panic disorder, a specific fear is a phobia, and anxiety with flashbacks after trauma is PTSD.',FRA),
  q(MENT,'Which feature distinguishes anorexia nervosa from bulimia nervosa?','Food restriction causing a very low body weight',['Episodes of binge eating followed by vomiting','A distorted belief about body shape or size','Use of laxatives to control weight'],'C','In anorexia, restriction leads to a dangerously low body weight. People with bulimia binge and then compensate, but usually maintain a normal weight. Distorted body image and purging can occur in both.',FRA)
 ],23)
};
